{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Gentle Aromatherapy Experiences</title>
  <meta name="description" content="A safety-first, sensory series of aromatherapy events led by {{PRACTITIONER_NAME}} in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme-earthy">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav">
        <a href="/services.html">Offerings</a>
        <a href="/blends.html">Blends</a>
        <a href="/about.html">About</a>
        <a href="/book.html" class="cta">Book</a>
      </nav>
      <button class="hamburger" aria-label="menu" id="navToggle">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" role="region" aria-label="Intro">
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1 class="kicker">Seasonal scent series</h1>
          <h2 class="title">A slow, safety-first practice of scent with {{PRACTITIONER_NAME}}</h2>
          <p class="lead">Join an intimate events series where we explore single-note and blended aromatics — rooted in craft, guided by safety, and composed like poetry.</p>
          <p class="meta">{{TAGLINE}}</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/services.html">View events</a>
          </div>
        </div>
        <div class="hero-art" aria-hidden="true">
          <svg class="bloom" viewBox="0 0 600 400" preserveAspectRatio="xMidYMid meet">
            <defs>
              <linearGradient id="gWarm" x1="0" x2="1">
                <stop offset="0" stop-color="#f3e9dd" />
                <stop offset="1" stop-color="#e9d3bf" />
              </linearGradient>
            </defs>
            <rect width="100%" height="100%" fill="url(#gWarm)" />
            <g opacity="0.9">
              <path d="M80 300 C140 200 220 180 340 220 C460 260 520 160 560 120" stroke="#8a6748" stroke-width="3" fill="none" stroke-linecap="round" />
              <circle cx="180" cy="140" r="64" fill="#c9a686" opacity="0.6" />
              <ellipse cx="420" cy="260" rx="88" ry="46" fill="#b48b63" opacity="0.35" />
            </g>
          </svg>
        </div>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social-proof" aria-label="Praise">
      <div class="wrap">
        <h3 class="section-title">Whispers from the circle</h3>
        <div class="proof-grid">
          <blockquote>"A gentle, guided way to meet scent — I left with a small blend and a calmer chest."<cite>— L.M., workshop attendee</cite></blockquote>
          <blockquote>"Thoughtful instruction and clear safety guidance. I learned patch testing and more."<cite>— A.R., repeat guest</cite></blockquote>
          <blockquote>"Beautiful space, earthy tone, and practical tips for everyday use."<cite>— S.K., local\, {{CITY}}</cite></blockquote>
        </div>
      </div>
    </section>

    <!-- BENEFITS -->
    <section class="benefits" aria-label="Benefits">
      <div class="wrap">
        <h3 class="section-title">What attendees take home</h3>
        <ul class="benefit-list">
          <li><strong>Craft skills:</strong> Learn to compose blends (top, middle, base) and build a small sampler.
          </li>
          <li><strong>Safety-first methods:</strong> Practical dilution guidance, patch test technique, and storage best practices.
          </li>
          <li><strong>Mindful ritual:</strong> Short scent meditations and journaling prompts to make aromatherapy personal and practical.</li>
        </ul>
      </div>
    </section>

    <!-- PROCESS -->
    <section class="process" aria-label="How it works">
      <div class="wrap">
        <h3 class="section-title">How the events flow</h3>
        <ol class="process-steps">
          <li><strong>Gather:</strong> Small group introductions and safety checklist (allergies, pregnancy, pet notes).</li>
          <li><strong>Explore:</strong> Single-note smelling, aroma vocabulary, and guided inhalations.</li>
          <li><strong>Create:</strong> Compose a blend with measured dilution and label it to take home.</li>
          <li><strong>Reflect:</strong> Share impressions and receive aftercare guidance for safe daily use.</li>
        </ol>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq" aria-label="Frequently asked questions">
      <div class="wrap">
        <h3 class="section-title">Questions and careful answers</h3>
        <div class="faq-grid">
          <div class="qa">
            <h4>How do you recommend diluting essential oils?</h4>
            <p>We teach simple, conservative dilution ratios using carrier oils. Typical guidance in events is 1–2% for daily roller blends for adults. Always follow product labels and avoid undiluted application.</p>
          </div>
          <div class="qa">
            <h4>What's a patch test and why do we do it?</h4>
            <p>A patch test checks for skin sensitivity: apply a small diluted amount behind the ear or inner forearm, wait 24 hours, and look for redness or irritation. We emphasize patch testing during every hands-on session.</p>
          </div>
          <div class="qa">
            <h4>Are essential oils safe around pets?</h4>
            <p>Some oils can be unsafe for animals. We provide pet-safety guidance and recommend avoiding strong topical or diffused exposure around cats and birds without veterinary advice.</p>
          </div>
          <div class="qa">
            <h4>Can pregnant or nursing people attend?</h4>
            <p>We welcome pregnant or nursing attendees but stress consultation with a healthcare provider. We always offer gentle, modified options and avoid certain oils commonly advised against in pregnancy.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- LEAD MAGNET -->
    <section class="lead-magnet" aria-label="Download">
      <div class="wrap">
        <div class="magnet-grid">
          <div>
            <h3 class="section-title">Free guide: Home Safety Starter</h3>
            <p>Sign up for a concise PDF covering dilution charts, patch testing steps, and a seasonal sampling list. A practical leaflet to keep on your shelf.</p>
            <form id="subscribeForm" class="subscribe-form" novalidate>
              <label for="email">Email</label>
              <input type="email" id="email" name="email" placeholder="you@domain.com" required>
              <button type="submit" class="btn primary">Send the guide</button>
              <p class="fine-print">We respect your privacy. No medical promises — only safe scent tips.</p>
            </form>
          </div>
          <div class="magnet-art" aria-hidden="true">
            <svg viewBox="0 0 200 200" class="leaflet">
              <defs>
                <linearGradient id="lg" x1="0" x2="1"><stop offset="0" stop-color="#ffd"/><stop offset="1" stop-color="#f5e6d9"/></linearGradient>
              </defs>
              <rect width="100%" height="100%" fill="url(#lg)"/>
              <g fill="#a07a58" opacity="0.7"><path d="M50 150 Q80 60 140 120"/></g>
            </svg>
          </div>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta-strip" aria-label="Call to action">
      <div class="wrap cta-inner">
        <div>
          <h3>Reserve a seat in the next circle</h3>
          <p class="muted">Small groups. Clear safety brief. Bring curiosity.</p>
        </div>
        <div>
          <a class="btn primary" href="/book.html">Book an event</a>
          <a class="btn ghost" href="/contact.html">Ask a question</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{PRACTITIONER_NAME}} — {{CITY}}, {{STATE}}</p>
      </div>
      <nav>
        <a href="/services.html">Offerings</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/shop.html">Shop</a>
        <a href="/contact.html">Contact</a>
      </nav>
      <div class="contact">
        <a href="tel:{{PHONE}}">{{PHONE}}</a>
        <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
