{"path":"assets/css/styles.css","content":"/* Earthy warm theme — minimal poetic */
:root{
  --bg:#fbf7f2;
  --panel:#fff6ef;
  --accent:#a07a58; /* warm brown */
  --muted:#7b6b5d;
  --accent-2:#d8b59b;
  --radius:12px;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:var(--muted);background:var(--bg) url('../assets/img/pattern.svg') repeat fixed;padding-bottom:4rem;}
.wrap{max-width:var(--max-width);margin:0 auto;padding:2rem}
.site-header{backdrop-filter:blur(4px);background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.35));position:sticky;top:0;z-index:40;border-bottom:1px solid rgba(160,122,88,0.06)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent);text-decoration:none}
.main-nav a{margin-left:1rem;color:var(--muted);text-decoration:none}
.main-nav a.cta{background:transparent;border:1px solid var(--accent);padding:0.45rem 0.8rem;border-radius:8px;color:var(--accent)}
.hamburger{display:none;background:none;border:0;font-size:1.2rem}
.hero{padding:3rem 0}
.hero-grid{display:grid;grid-template-columns:1fr 340px;gap:2rem;align-items:center}
.hero .kicker{font-size:0.95rem;color:var(--accent-2);text-transform:uppercase;letter-spacing:1px}
.hero .title{font-size:clamp(1.6rem,2.8vw,2.6rem);margin:0.2rem 0;color:#6b4f3a}
.hero .lead{color:var(--muted);max-width:40rem}
.hero-ctas .btn{margin-right:0.6rem}
.btn{display:inline-block;padding:0.6rem 1rem;border-radius:10px;text-decoration:none;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent),#b67c55);color:#fff}
.btn.ghost{background:transparent;border:1px solid rgba(120,90,60,0.12);color:var(--muted)}
.hero-art svg{width:100%;height:auto;border-radius:var(--radius);box-shadow:0 10px 30px rgba(101,66,45,0.06)}
.social-proof{padding:2rem 0}
.section-title{font-size:1.05rem;color:#5b3f2c;margin-bottom:0.8rem}
.proof-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
.proof-grid blockquote{background:var(--panel);padding:1rem;border-radius:10px;font-style:italic;color:#4d3a2c}
.proof-grid cite{display:block;margin-top:0.6rem;font-style:normal;color:var(--muted);font-weight:600}
.benefits,.process{padding:2rem 0}
.benefit-list{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;list-style:none;padding:0}
.benefit-list li{background:#fff;padding:1rem;border-radius:10px;border-left:4px solid var(--accent-2)}
.process-steps{list-style:none;padding:0;display:grid;gap:0.6rem}
.process-steps li{background:var(--panel);padding:0.9rem;border-radius:8px}
.faq{background:linear-gradient(180deg,rgba(255,255,255,0.9),rgba(250,245,241,0.9));padding:2rem;border-radius:14px;margin:2rem 0}
.faq-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem}
.qa h4{margin:0 0 0.4rem 0;color:#5a3f33}
.lead-magnet{padding:2rem 0}
.magnet-grid{display:grid;grid-template-columns:1fr 320px;gap:1.2rem;align-items:center}
.subscribe-form{display:grid;gap:0.6rem}
.subscribe-form input[type="email"]{padding:0.6rem;border-radius:8px;border:1px solid #ead6c2}
.subscribe-form .fine-print{font-size:0.8rem;color:var(--muted)}
.cta-strip{margin-top:2rem;padding:1.2rem;border-radius:12px;background:linear-gradient(90deg,rgba(160,122,88,0.08),rgba(216,181,155,0.04));display:block}
.cta-inner{display:flex;justify-content:space-between;align-items:center}
.site-footer{margin-top:3rem;padding:2rem 0;color:var(--muted)}
.footer-grid{display:grid;grid-template-columns:1fr auto 1fr;gap:1rem;align-items:center}
.footer-grid nav a{margin-left:0.8rem;color:var(--muted);text-decoration:none}
.contact a{display:block;color:var(--muted);text-decoration:none}
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .proof-grid{grid-template-columns:1fr}
  .benefit-list{grid-template-columns:1fr}
  .faq-grid{grid-template-columns:1fr}
  .magnet-grid{grid-template-columns:1fr}
  .hamburger{display:block}
  .main-nav{display:none}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Simple interaction: nav toggle and subscribe form handling
  var navToggle = document.getElementById('navToggle');
  navToggle && navToggle.addEventListener('click', function(){
    var nav = document.querySelector('.main-nav');
    if(!nav) return;
    if(nav.style.display === 'block') nav.style.display = '';
    else nav.style.display = 'block';
  });

  var form = document.getElementById('subscribeForm');
  form && form.addEventListener('submit', function(e){
    e.preventDefault();
    var email = form.querySelector('input[type="email"]').value || '';
    var ok = /\S+@\S+\.\S+/.test(email);
    if(!ok){
      alert('Please enter a valid email address to receive the safety starter guide.');
      return;
    }
    // Simulate success — no external calls
    form.reset();
    var btn = form.querySelector('button');
    var old = btn.textContent;
    btn.textContent = 'Sent — check your inbox';
    btn.disabled = true;
    setTimeout(function(){ btn.textContent = old; btn.disabled = false; }, 3500);
  });

  // Convenience: smooth scroll for internal links
  document.addEventListener('click', function(e){
    var a = e.target.closest('a');
    if(!a) return;
    var href = a.getAttribute('href');
    if(href && href.startsWith('#')){
      e.preventDefault();
      var el = document.querySelector(href);
      if(el) el.scrollIntoView({behavior:'smooth'});
    }
  });
})();
"} 
